def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    # legend: strips hanging from the top row
    legend = {}
    for x in range(W):
        c = g[0, x]
        if c == bg:
            continue
        n = 0
        while n < H and g[n, x] == c:
            n += 1
        legend[int(c)] = n
    # bars: columns standing on the bottom row
    bars = {}
    for x in range(W):
        c = g[H - 1, x]
        if c == bg:
            continue
        y = H - 1
        while y >= 0 and g[y, x] != bg:
            y -= 1
        top = y + 1
        bars.setdefault(int(c), []).append((H - top, x, top))
    for c, n in legend.items():
        lst = sorted(bars.get(c, []), key=lambda t: -t[0])
        if 1 <= n <= len(lst):
            h, x, top = lst[n - 1]
            out[top:H, x] = c
            emit(out.copy(), f"Legend colour {c} has height {n}: fill the {n}-th tallest bar capped with {c} (column {x}, height {h}) entirely in colour {c}.")
    emit(out.copy(), "All legend instructions applied.")
    return out
